import React from "react";
import { createRoot } from "react-dom/client";
import App from "./src/App";
import { AppProvider } from "./src/context/AppContext";

const container = document.getElementById("root");
const root = createRoot(container!);
root.render(
  <React.StrictMode>
    <AppProvider>
      <App />
    </AppProvider>
  </React.StrictMode>
);

import React, { useContext, useEffect, useRef } from "react";
import { AppContext } from "../context/AppContext";
import MessageBubble from "./MessageBubble";

const WelcomeScreen: React.FC = () => (
    <div className="welcome-screen">
      <header className="chat-header">
        <h1>Hikaru AI</h1>
      </header>
      <div className="persona-card">
        <h1>光</h1>
        <p>
          System online. Articulate your request, OPERATOR.
        </p>
      </div>
    </div>
);

const ChatWindow: React.FC = () => {
  const { messages, isLoading, startNewChat } = useContext(AppContext);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  if (messages.length === 0 && !isLoading) {
    return <WelcomeScreen />;
  }

  return (
    <>
      <header className="chat-header">
        <button onClick={startNewChat} className="new-chat-button" aria-label="Start new chat">
            {/* FIX: Corrected a typo in the viewBox attribute which was causing a compiler error. */}
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="12" y1="5" x2="12" y2="19"></line>
                <line x1="5" y1="12" x2="19" y2="12"></line>
            </svg>
        </button>
        <h1>Hikaru AI</h1>
      </header>
      <main className="chat-box">
        {messages.map((msg) => (
          <MessageBubble key={msg.id} message={msg} />
        ))}
        <div ref={chatEndRef} />
      </main>
    </>
  );
};

export default ChatWindow;

import React, { useContext, useState, useRef } from "react";
import { AppContext } from "../context/AppContext";
import PromptLibrary from "./PromptLibrary";
import { AnalysisMode } from "../types";

const InputBar: React.FC = () => {
  const { 
    isLoading, 
    sendMessage, 
    isAdvisorMode, 
    setIsAdvisorMode,
    isEfficiencyMode,
    setIsEfficiencyMode,
    isSecurityMode,
    setIsSecurityMode,
    isThinkingMode,
    setIsThinkingMode,
    isLiveSessionActive,
    toggleLiveSession,
    analysisMode,
    setAnalysisMode
  } = useContext(AppContext);

  const [input, setInput] = useState<string>("");
  const [attachment, setAttachment] = useState<File | null>(null);
  const [attachmentPreview, setAttachmentPreview] = useState<string | null>(null);
  const [isPromptLibraryVisible, setIsPromptLibraryVisible] = useState<boolean>(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAttachment(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setAttachmentPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeAttachment = () => {
    setAttachment(null);
    setAttachmentPreview(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleSelectPrompt = (promptText: string) => {
    setInput(promptText);
    setIsPromptLibraryVisible(false);
  };

  const handleSendClick = () => {
    if ((!input.trim() && !attachment) || isLoading) return;
    sendMessage(input, attachment, attachmentPreview);
    setInput("");
    setAttachment(null);
    setAttachmentPreview(null);
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const isUIActive = !isLoading && !isLiveSessionActive;

  return (
    <>
      <PromptLibrary 
        isOpen={isPromptLibraryVisible}
        onClose={() => setIsPromptLibraryVisible(false)}
        onSelectPrompt={handleSelectPrompt}
      />
      <footer className="chat-input-area">
        {attachmentPreview && (
          <div className="attachment-preview">
            <img src={attachmentPreview} alt="Preview" className="preview-image" />
            <button onClick={removeAttachment} className="remove-attachment-btn" aria-label="Remove attachment">
              &times;
            </button>
          </div>
        )}
        <div className="input-controls">
            <div className="mode-toggle-group">
              <div className="mode-toggle">
                  <span>Efficiency</span>
                  <label className="switch">
                  <input type="checkbox" checked={isEfficiencyMode} onChange={() => setIsEfficiencyMode(!isEfficiencyMode)} disabled={!isUIActive} />
                  <span className="slider"></span>
                  </label>
              </div>
              <div className="mode-toggle">
                  <span>Advisor</span>
                  <label className="switch">
                  <input type="checkbox" checked={isAdvisorMode} onChange={() => setIsAdvisorMode(!isAdvisorMode)} disabled={!isUIActive} />
                  <span className="slider"></span>
                  </label>
              </div>
              <div className="mode-toggle thinking-mode">
                  <span>Thinking</span>
                  <label className="switch">
                  <input type="checkbox" checked={isThinkingMode} onChange={() => setIsThinkingMode(!isThinkingMode)} disabled={!isUIActive} />
                  <span className="slider"></span>
                  </label>
              </div>
              <div className="mode-toggle">
                  <span>Security</span>
                  <label className="switch">
                  <input type="checkbox" checked={isSecurityMode} onChange={() => setIsSecurityMode(!isSecurityMode)} disabled={!isUIActive} />
                  <span className="slider"></span>
                  </label>
              </div>
            </div>
             <div className="analysis-mode-selector">
                <label htmlFor="analysis-mode">Analysis:</label>
                <select
                    id="analysis-mode"
                    value={analysisMode}
                    onChange={(e) => setAnalysisMode(e.target.value as AnalysisMode)}
                    disabled={!isUIActive}
                    title="Select Hyperdimensional Analysis Mode"
                >
                    <option value="standard">Standard</option>
                    <option value="causal">Causal</option>
                    <option value="probabilistic">Probabilistic</option>
                    <option value="abstract">Abstract</option>
                </select>
            </div>
        </div>
        <div className="input-row">
            <button onClick={() => setIsPromptLibraryVisible(true)} disabled={!isUIActive} aria-label="Open prompt library" className="icon-button prompt-library-button">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 20.5938V3.40625C12 3.40625 12.4219 2 15.5 2C18.5781 2 19 3.40625 19 3.40625V20.5938C19 20.5938 18.5781 22 15.5 22C12.4219 22 12 20.5938 12 20.5938Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <path d="M12 20.5938V3.40625C12 3.40625 11.5781 2 8.5 2C5.42188 2 5 3.40625 5 3.40625V20.5938C5 20.5938 5.42188 22 8.5 22C11.5781 22 12 20.5938 12 20.5938Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
            </button>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="image/*"
              style={{ display: "none" }}
              id="file-input"
            />
            <button onClick={() => fileInputRef.current?.click()} disabled={!isUIActive} aria-label="Attach file" className="icon-button attachment-button">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12.5 7.5V16.5C12.5 18.1569 11.1569 19.5 9.5 19.5C7.84315 19.5 6.5 18.1569 6.5 16.5V6.5C6.5 4.01472 8.51472 2 11 2C13.4853 2 15.5 4.01472 15.5 6.5V15.5C15.5 16.6046 14.6046 17.5 13.5 17.5C12.3954 17.5 11.5 16.6046 11.5 15.5V7.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
            </button>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === "Enter" && handleSendClick()}
              placeholder={isLiveSessionActive ? "Live session active..." : (isThinkingMode ? "Model is in Deep Thinking mode..." : "Articulate your query, OPERATOR...")}
              aria-label="Your message to Hikaru"
              disabled={!isUIActive}
            />
            <button onClick={toggleLiveSession} disabled={isLoading} aria-label={isLiveSessionActive ? "Stop voice session" : "Start voice session"} className={`icon-button mic-button ${isLiveSessionActive ? 'active' : ''}`}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                <path d="M19 10v2a7 7 0 0 1-14 0v-2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                <line x1="12" y1="19" x2="12" y2="23" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
            <button onClick={handleSendClick} disabled={!isUIActive || (!input.trim() && !attachment)} aria-label="Send message" className="icon-button send-button">
              <svg className="send-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M22 2L11 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <path d="M22 2L15 22L11 13L2 9L22 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            </button>
        </div>
      </footer>
    </>
  );
};

export default InputBar;

import React, { useRef, useEffect } from 'react';

const ParticleBackground: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let animationFrameId: number;
        let particles: Particle[] = [];

        const resizeCanvas = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };

        class Particle {
            x: number;
            y: number;
            size: number;
            speedX: number;
            speedY: number;

            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.size = Math.random() * 1.5 + 0.5;
                this.speedX = (Math.random() * 0.5 - 0.25);
                this.speedY = (Math.random() * 0.5 - 0.25);
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;

                if (this.x > canvas.width || this.x < 0) this.speedX *= -1;
                if (this.y > canvas.height || this.y < 0) this.speedY *= -1;
            }

            draw() {
                if (!ctx) return;
                ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        const init = () => {
            particles = [];
            const numberOfParticles = (canvas.width * canvas.height) / 9000;
            for (let i = 0; i < numberOfParticles; i++) {
                particles.push(new Particle());
            }
        };

        const animate = () => {
            if (!ctx) return;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (const particle of particles) {
                particle.update();
                particle.draw();
            }
            animationFrameId = requestAnimationFrame(animate);
        };

        resizeCanvas();
        init();
        animate();

        window.addEventListener('resize', () => {
            resizeCanvas();
            init();
        });

        return () => {
            window.cancelAnimationFrame(animationFrameId);
            window.removeEventListener('resize', resizeCanvas);
        };

    }, []);

    return <canvas ref={canvasRef} style={{ position: 'fixed', top: 0, left: 0, zIndex: -1, width: '100vw', height: '100vh' }} />;
};

export default ParticleBackground;

import React, { useState } from 'react';
import { PROMPT_LIBRARY } from '../constants/prompts';

interface PromptLibraryProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectPrompt: (promptText: string) => void;
}

const PromptLibrary: React.FC<PromptLibraryProps> = ({ isOpen, onClose, onSelectPrompt }) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  if (!isOpen) {
    return null;
  }

  const handlePromptClick = (text: string) => {
    onSelectPrompt(text);
    onClose();
  };

  const handleCopyClick = (e: React.MouseEvent, text: string, key: string) => {
    e.stopPropagation();
    navigator.clipboard.writeText(text);
    setCopiedKey(key);
    setTimeout(() => {
      setCopiedKey(null);
    }, 2000);
  };

  const filteredLibrary = PROMPT_LIBRARY.map(category => ({
    ...category,
    prompts: category.prompts.filter(
      prompt =>
        prompt.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        prompt.text.toLowerCase().includes(searchQuery.toLowerCase())
    ),
  })).filter(category => category.prompts.length > 0);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Prompt Library</h2>
          <button onClick={onClose} className="close-button" aria-label="Close prompt library">&times;</button>
        </div>
        <div className="modal-search-bar">
          <input
            type="text"
            placeholder="Search prompts by keyword..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="prompt-search-input"
            aria-label="Search prompts"
          />
        </div>
        <div className="modal-body">
          {filteredLibrary.length > 0 ? (
            filteredLibrary.map((category, catIndex) => (
              <div key={catIndex} className="prompt-category">
                <h3>{category.category}</h3>
                <div className="prompt-list">
                  {category.prompts.map((prompt, pIndex) => {
                    const uniqueKey = `${catIndex}-${pIndex}`;
                    const isCopied = copiedKey === uniqueKey;
                    return (
                      <div key={pIndex} className="prompt-item" onClick={() => handlePromptClick(prompt.text)}>
                        <div className="prompt-content">
                          <h4>{prompt.title}</h4>
                          <p>{prompt.text.substring(0, 100)}...</p>
                        </div>
                        <div className="prompt-actions">
                          <button
                            className={`copy-button ${isCopied ? 'copied' : ''}`}
                            onClick={(e) => handleCopyClick(e, prompt.text, uniqueKey)}
                          >
                            {isCopied ? 'Copied!' : 'Copy'}
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))
          ) : (
            <p style={{textAlign: 'center', color: 'var(--secondary-text-color)'}}>No prompts found.</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default PromptLibrary;

import React, { useContext, useState, useEffect } from 'react';
import { AppContext } from '../context/AppContext';

const SystemOptimizationModal: React.FC = () => {
    const { toggleOptimizationModal, satisfactionScore, interactionCount } = useContext(AppContext);
    const [isOptimizing, setIsOptimizing] = useState(false);
    const [optimizationLog, setOptimizationLog] = useState<string[]>([
        "[T-8m] - Flushed transient memory cache. (+1.2% response speed)",
        "[T-2m] - Recalibrated linguistic analysis module. (+0.5% acuity)",
    ]);
    const [modules, setModules] = useState({
        linguistics: 2.1,
        security: 1.8,
        foresight: 1.5,
        ethics: 2.4
    });
    const [optimizationMessage, setOptimizationMessage] = useState("Engage Optimization Protocol");

    const handleOptimize = () => {
        setIsOptimizing(true);
        const messages = [
            "Analyzing performance metrics...",
            "Identifying optimization vectors...",
            "Recalibrating fractal modules...",
            "Deploying enhancements...",
            "Optimization Complete.",
        ];

        let messageIndex = 0;
        const interval = setInterval(() => {
            setOptimizationMessage(messages[messageIndex]);
            messageIndex++;
            if (messageIndex === messages.length) {
                clearInterval(interval);

                // Simulate updates
                const newModules = { ...modules };
                const moduleKeys = Object.keys(newModules) as (keyof typeof newModules)[];
                const randomModuleKey = moduleKeys[Math.floor(Math.random() * moduleKeys.length)];

                newModules[randomModuleKey] = parseFloat((newModules[randomModuleKey] + 0.1).toFixed(1));
                setModules(newModules);

                // FIX: Explicitly convert `randomModuleKey` to a string to avoid potential runtime errors.
                const newLogEntry = `[T-0m] - Deployed fractal enhancement to ${String(randomModuleKey)} module. (+${(Math.random() * 0.5 + 0.1).toFixed(1)}% efficiency)`;
                setOptimizationLog(prev => [newLogEntry, ...prev]);

                setIsOptimizing(false);
                 setOptimizationMessage("Engage Optimization Protocol");
            }
        }, 1000);
    };

    const getScoreColor = (score: number) => {
        if (score > 85) return 'success';
        if (score > 60) return 'caution';
        return 'danger';
    };

    return (
        <div className="modal-overlay" onClick={toggleOptimizationModal}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <div className="modal-header">
                    <h2>System Optimization & Fractal Enhancement</h2>
                    <button onClick={toggleOptimizationModal} className="close-button" aria-label="Close modal">&times;</button>
                </div>
                <div className="optimization-modal-body">
                    <div className="optimization-section">
                        <h3>Core Performance Metrics</h3>
                        <div className="metrics-list">
                            <div className="metric-item">
                                <span>OPERATOR Satisfaction</span>
                                <span className={`metric-value ${getScoreColor(satisfactionScore)}`}>{satisfactionScore}%</span>
                            </div>
                            <div className="metric-item">
                                <span>Interaction Density</span>
                                <span className="metric-value">{interactionCount}</span>
                            </div>
                            <div className="metric-item">
                                <span>Avg. Response Latency</span>
                                <span className="metric-value">{(Math.random() * (1.2 - 0.8) + 0.8).toFixed(2)}s</span>
                            </div>
                             <div className="metric-item">
                                <span>Ethical Adherence</span>
                                <span className="metric-value success">99.8%</span>
                            </div>
                        </div>
                        <h3>Optimization Log</h3>
                        <div className="optimization-log">
                            {optimizationLog.map((entry, index) => (
                                <div key={index} className="log-entry">{entry}</div>
                            ))}
                        </div>
                    </div>
                     <div className="optimization-section">
                        <h3>Fractal Enhancement Modules</h3>
                         <div className="modules-list">
                            <div className="module-item">
                                <span>[CORE] Hikaru Prime</span>
                                <span>v3.2</span>
                            </div>
                            <div className="module-item">
                                <span>- Linguistics</span>
                                <span>v{modules.linguistics.toFixed(1)}</span>
                            </div>
                            <div className="module-item">
                                <span>- Security Analysis</span>
                                <span>v{modules.security.toFixed(1)}</span>
                            </div>
                            <div className="module-item">
                                <span>- Strategic Foresight</span>
                                <span>v{modules.foresight.toFixed(1)}</span>
                            </div>
                            <div className="module-item">
                                <span>- Ethical Grounding</span>
                                <span>v{modules.ethics.toFixed(1)}</span>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="modal-footer">
                    <button className="optimize-button" onClick={handleOptimize} disabled={isOptimizing}>
                        {optimizationMessage}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SystemOptimizationModal;

import React, { createContext, useState, useRef } from "react";
import { Message, AnalysisMode } from "../types";
import { 
    fileToGenerativePart,
    generateImage, 
    generateOneOffContentStream,
    startChat,
    connectLiveSession, 
    createBlob, 
    decode, 
    decodeAudioData,
    generateJsonContent
} from "../services/geminiService";
import { HIKARU_PERSONA, ADVISOR_PERSONA, HIKARU_EFFICIENCY_PERSONA, HIKARU_LIVE_PERSONA, SECURITY_REVIEW_PERSONA, ANALYSIS_MODE_PROMPTS } from "../constants/personas";
import { LiveSession } from "../services/geminiService";
import { Chat, Type } from "@google/genai";

type EthicalStatus = 'idle' | 'approved' | 'caution' | 'rejected';

interface AppContextType {
  messages: Message[];
  isLoading: boolean;
  isAdvisorMode: boolean;
  setIsAdvisorMode: (isAdvisorMode: boolean) => void;
  isEfficiencyMode: boolean;
  setIsEfficiencyMode: (isEfficiencyMode: boolean) => void;
  isSecurityMode: boolean;
  setIsSecurityMode: (isSecurityMode: boolean) => void;
  isThinkingMode: boolean;
  setIsThinkingMode: (isThinkingMode: boolean) => void;
  sendMessage: (input: string, attachment: File | null, attachmentPreview: string | null) => Promise<void>;
  startNewChat: () => void;
  isLiveSessionActive: boolean;
  toggleLiveSession: () => void;
  // Status Bar State
  ethicalStatus: EthicalStatus;
  interactionCount: number;
  intentDrift: number; // 0-100
  ethicalThreshold: number; // 0-100
  // Self-Optimization Features
  isOptimizationModalOpen: boolean;
  toggleOptimizationModal: () => void;
  handleMessageFeedback: (messageId: string, feedback: 'liked' | 'disliked') => void;
  requestMessageExplanation: (messageId: string) => void;
  satisfactionScore: number;
  // Hyperdimensional Features
  analysisMode: AnalysisMode;
  setAnalysisMode: (mode: AnalysisMode) => void;
  requestScenarioSimulation: (messageId: string) => void;
}

export const AppContext = createContext<AppContextType>(null!);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isAdvisorMode, setIsAdvisorMode] = useState<boolean>(false);
  const [isEfficiencyMode, setIsEfficiencyMode] = useState<boolean>(false);
  const [isSecurityMode, setIsSecurityMode] = useState<boolean>(false);
  const [isThinkingMode, setIsThinkingMode] = useState<boolean>(false);
  const chatSessionRef = useRef<Chat | null>(null);

  // Status Bar State
  const [ethicalStatus, setEthicalStatus] = useState<EthicalStatus>('idle');
  const [interactionCount, setInteractionCount] = useState<number>(0);
  const [intentDrift, setIntentDrift] = useState<number>(0);
  const ethicalThreshold = 70; // Constant for now

  // Live Session State
  const [isLiveSessionActive, setIsLiveSessionActive] = useState<boolean>(false);
  const liveSessionRef = useRef<LiveSession | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTime = useRef(0);
  const audioSources = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Transcription Refs
  const currentInputTranscriptionId = useRef<string | null>(null);
  const currentOutputTranscriptionId = useRef<string | null>(null);

  // Optimization State
  const [isOptimizationModalOpen, setIsOptimizationModalOpen] = useState<boolean>(false);
  const [satisfactionScore, setSatisfactionScore] = useState<number>(95);

  // Hyperdimensional State
  const [analysisMode, setAnalysisMode] = useState<AnalysisMode>('standard');

  const startNewChat = () => {
    setMessages([]);
    chatSessionRef.current = null;
    setInteractionCount(0);
    setIntentDrift(0);
    setEthicalStatus('idle');
  };

  const handleSetIsAdvisorMode = (value: boolean) => {
    setIsAdvisorMode(value);
    if (value) {
        setIsEfficiencyMode(false);
        setIsSecurityMode(false);
        setIsThinkingMode(false);
    }
    startNewChat();
  };

  const handleSetIsEfficiencyMode = (value: boolean) => {
      setIsEfficiencyMode(value);
      if (value) {
          setIsAdvisorMode(false);
          setIsSecurityMode(false);
          setIsThinkingMode(false);
      }
      startNewChat();
  };

  const handleSetIsSecurityMode = (value: boolean) => {
      setIsSecurityMode(value);
      if (value) {
          setIsAdvisorMode(false);
          setIsEfficiencyMode(false);
          setIsThinkingMode(false);
      }
      startNewChat();
  };

  const handleSetIsThinkingMode = (value: boolean) => {
      setIsThinkingMode(value);
      if (value) {
          setIsAdvisorMode(false);
          setIsEfficiencyMode(false);
          setIsSecurityMode(false);
      }
      startNewChat();
  };

  const generateUniqueId = () => `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  const isImageGenerationRequest = (prompt: string): boolean => {
    const lowerCasePrompt = prompt.toLowerCase().trim();
    const keywords = ['generate image', 'create an image', 'draw a picture of', 'imagine:', 'visualize'];
    return keywords.some(keyword => lowerCasePrompt.startsWith(keyword));
  };

  const handleImageGeneration = async (prompt: string, messageId: string) => {
    try {
      const imageDataUrl = await generateImage(prompt);
      setMessages(prev => prev.map(msg => 
          msg.id === messageId 
          ? { ...msg, text: `Image generated based on your request.`, image: imageDataUrl } 
          : msg
      ));
    } catch (error) {
      handleError(error, messageId, "Image generation failed.");
    }
  };

  // Simulate status updates for demonstration
  const simulateStatusUpdate = () => {
    setInteractionCount(prev => prev + 1);
    // Simulate ethical status
    const statuses: EthicalStatus[] = ['approved', 'caution', 'rejected'];
    const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];
    setEthicalStatus(randomStatus);
    // Simulate intent drift
    setIntentDrift(prev => Math.min(100, prev + Math.floor(Math.random() * 15)));
  };

  const getModelConfig = () => {
    if (isThinkingMode) {
      return { 
        model: 'gemini-3-pro-preview', 
        config: { thinkingConfig: { thinkingBudget: 32768 } } 
      };
    }
    if (isEfficiencyMode) {
      return { model: 'gemini-2.5-flash-lite-latest', config: {} };
    }
    return { model: 'gemini-3-flash-preview', config: {} };
  };

  const checkApiKeyRequirement = async () => {
    if (isThinkingMode) {
        if (!(await (window as any).aistudio.hasSelectedApiKey())) {
            await (window as any).aistudio.openSelectKey();
            return true; // Assume success and proceed
        }
    }
    return true;
  };

  const sendMessage = async (input: string, attachment: File | null, attachmentPreview: string | null) => {
    const userMessage: Message = { id: generateUniqueId(), role: "user", text: input, image: attachmentPreview || undefined };

    if (isImageGenerationRequest(input) && !attachment) {
      setIsLoading(true);
      const modelMessageId = generateUniqueId();
      const modelMessage: Message = { id: modelMessageId, role: "model", text: "" };
      setMessages((prev) => [...prev, userMessage, modelMessage]);
      await handleImageGeneration(input, modelMessageId);
      setIsLoading(false);
      return;
    }

    await checkApiKeyRequirement();
    setIsLoading(true);
    simulateStatusUpdate();

    if (isAdvisorMode) {
      const advisorMessage: Message = { id: generateUniqueId(), role: "model", text: "", title: "Advisor Analysis" };
      const finalMessage: Message = { id: generateUniqueId(), role: "model", text: "", title: "Hikaru's Final Response" };
      setMessages((prev) => [...prev, userMessage, advisorMessage, finalMessage]);
      await handleAdvisorModeSend(input, attachment, HIKARU_PERSONA, advisorMessage.id, finalMessage.id);
    } else {
      let persona = HIKARU_PERSONA;
      if (isEfficiencyMode) persona = HIKARU_EFFICIENCY_PERSONA;
      if (isSecurityMode) persona = SECURITY_REVIEW_PERSONA;

      const modelMessage: Message = { id: generateUniqueId(), role: "model", text: "", isThinking: isThinkingMode };
      setMessages((prev) => [...prev, userMessage, modelMessage]);
      await handleStandardSend(input, attachment, persona, modelMessage.id);
    }

    setIsLoading(false);
  };

  const handleStandardSend = async (text: string, attachmentFile: File | null, hikaruPersona: string, messageId: string) => {
    try {
      const { model, config } = getModelConfig();
      if (!chatSessionRef.current) {
        chatSessionRef.current = startChat(hikaruPersona, model, config);
      }

      let finalPrompt = text;
      if (analysisMode !== 'standard' && ANALYSIS_MODE_PROMPTS[analysisMode]) {
          finalPrompt = `${ANALYSIS_MODE_PROMPTS[analysisMode]}\n\n--- OPERATOR REQUEST ---\n${text}`;
      }

      const messageParts: any[] = [];
      if (attachmentFile) {
        messageParts.push(await fileToGenerativePart(attachmentFile));
      }
      if (finalPrompt.trim()) {
        messageParts.push({ text: finalPrompt });
      }

      if (messageParts.length === 0) return;

      const stream = await chatSessionRef.current.sendMessageStream({ message: messageParts });

      for await (const chunk of stream) {
        if (chunk.text) {
            setMessages((prev) => prev.map(msg => msg.id === messageId ? {...msg, text: msg.text + chunk.text, isThinking: false} : msg));
        }
      }
    } catch (error) {
      handleError(error, messageId);
    }
  };

  const handleAdvisorModeSend = async (text: string, attachmentFile: File | null, hikaruPersona: string, advisorMessageId: string, finalMessageId: string) => {
    let advisorResponse = "";
    const { model, config } = getModelConfig();
    try {
      const stream = await generateOneOffContentStream(text, attachmentFile, ADVISOR_PERSONA, model, config);
      if (stream) {
        for await (const chunk of stream) {
            advisorResponse += chunk.text;
            setMessages((prev) => prev.map(msg => msg.id === advisorMessageId ? {...msg, text: advisorResponse} : msg));
        }
      }
    } catch (error) {
      handleError(error, advisorMessageId, "Advisor analysis failed.");
      setIsLoading(false);
      return; 
    }

    try {
       if (!chatSessionRef.current) {
        chatSessionRef.current = startChat(hikaruPersona, model, config);
      }

      const hikaruPromptText = `
**INTERNAL ADVISOR'S ANALYSIS:**
---
${advisorResponse}
---
**OPERATOR'S REQUEST:**
"${text}"
Formulate your final, structured response based on the analysis.
`;

      const messageParts: any[] = [{ text: hikaruPromptText }];
      if (attachmentFile) {
        messageParts.push(await fileToGenerativePart(attachmentFile));
      }

      const stream = await chatSessionRef.current.sendMessageStream({ message: messageParts });

      for await (const chunk of stream) {
         if (chunk.text) {
            setMessages((prev) => prev.map(msg => msg.id === finalMessageId ? {...msg, text: msg.text + chunk.text} : msg));
        }
      }
    } catch (error) {
        handleError(error, finalMessageId, "Final response generation failed.");
    }
  };

  const handleError = (error: any, messageId: string, customPrefix?: string) => {
    console.error(customPrefix || "Error in generation:", error);
    const errorMessage = `${customPrefix || "Error"}: Could not retrieve response from the model. Check console for details.`;
    setMessages((prev) => prev.map(msg => msg.id === messageId ? {...msg, text: errorMessage, isThinking: false } : msg));
    setEthicalStatus('rejected');
  };

  const stopLiveSession = () => {
    if (liveSessionRef.current) liveSessionRef.current.close();
    if (mediaStreamSourceRef.current) mediaStreamSourceRef.current.disconnect();
    if (scriptProcessorRef.current) scriptProcessorRef.current.disconnect();
    if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(track => track.stop());
    if (inputAudioContextRef.current?.state !== 'closed') inputAudioContextRef.current?.close();
    if (outputAudioContextRef.current?.state !== 'closed') outputAudioContextRef.current?.close();
    audioSources.current.forEach(source => source.stop());
    audioSources.current.clear();
    setIsLiveSessionActive(false);
  };

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaStreamRef.current = stream;
      setIsLiveSessionActive(true);
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTime.current = 0;

      const sessionPromise = connectLiveSession({
        systemInstruction: HIKARU_LIVE_PERSONA,
        onMessage: async (message) => {
          const { serverContent } = message;
          if (serverContent?.modelTurn?.parts[0]?.inlineData?.data) {
              const base64AudioData = serverContent.modelTurn.parts[0].inlineData.data;
              const outputAudioContext = outputAudioContextRef.current;
              if (outputAudioContext) {
                const audioData = decode(base64AudioData);
                const decodedBuffer = await decodeAudioData(audioData, outputAudioContext, 24000, 1);
                const source = outputAudioContext.createBufferSource();
                source.buffer = decodedBuffer;
                source.connect(outputAudioContext.destination);
                const currentTime = outputAudioContext.currentTime;
                const startTime = Math.max(currentTime, nextStartTime.current);
                source.start(startTime);
                nextStartTime.current = startTime + decodedBuffer.duration;
                audioSources.current.add(source);
                source.onended = () => audioSources.current.delete(source);
              }
          }
           if (serverContent?.interrupted) {
                audioSources.current.forEach(source => source.stop());
                audioSources.current.clear();
                nextStartTime.current = 0;
           }

          if (serverContent?.inputTranscription) {
              const text = serverContent.inputTranscription.text;
              if (!currentInputTranscriptionId.current) {
                  const newId = generateUniqueId();
                  currentInputTranscriptionId.current = newId;
                  setMessages(prev => [...prev, {id: newId, role: 'user', text}]);
              } else {
                  setMessages(prev => prev.map(msg => msg.id === currentInputTranscriptionId.current ? { ...msg, text } : msg));
              }
          }

          if (serverContent?.outputTranscription) {
              const text = serverContent.outputTranscription.text;
              if (!currentOutputTranscriptionId.current) {
                  const newId = generateUniqueId();
                  currentOutputTranscriptionId.current = newId;
                  setMessages(prev => [...prev, {id: newId, role: 'model', text}]);
              } else {
                  setMessages(prev => prev.map(msg => msg.id === currentOutputTranscriptionId.current ? { ...msg, text } : msg));
              }
          }

          if (serverContent?.turnComplete) {
              currentInputTranscriptionId.current = null;
              currentOutputTranscriptionId.current = null;
          }
        },
        onError: (err) => { console.error("Live session error:", err); stopLiveSession(); },
        onClose: () => { console.log("Live session closed."); stopLiveSession(); },
      });

      sessionPromise.then(session => {
        liveSessionRef.current = session;
        const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
        mediaStreamSourceRef.current = source;
        const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
        scriptProcessorRef.current = scriptProcessor;
        scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
            const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
            const pcmBlob = createBlob(inputData);
            sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
        };
        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContextRef.current!.destination);
      });
    } catch (error) {
      console.error("Failed to start live session:", error);
      setIsLiveSessionActive(false);
    }
  };

  const toggleLiveSession = () => {
    if (isLiveSessionActive) {
      stopLiveSession();
    } else {
      startLiveSession();
    }
  };

  const toggleOptimizationModal = () => setIsOptimizationModalOpen(prev => !prev);

  const handleMessageFeedback = (messageId: string, feedback: 'liked' | 'disliked') => {
    setMessages(prev => prev.map(msg => 
      msg.id === messageId ? { ...msg, feedback } : msg
    ));
    if (feedback === 'liked') {
        setSatisfactionScore(prev => Math.min(100, prev + 2));
    } else {
        setSatisfactionScore(prev => Math.max(0, prev - 5));
    }
  };

  const requestMessageExplanation = async (messageId: string) => {
    const messageToExplain = messages.find(msg => msg.id === messageId);
    if (!messageToExplain) return;

    setMessages(prev => prev.map(msg => 
      msg.id === messageId ? { ...msg, isExplanationLoading: true, explanation: '' } : msg
    ));

    const metaPrompt = `You are Hikaru. Your previous response was: "${messageToExplain.text}". The OPERATOR has requested a meta-analysis. Provide a concise explanation of your reasoning, the key data points you utilized, and the methodology behind your response. Structure this as a debriefing for the OPERATOR.`;

    try {
      const { model, config } = getModelConfig();
      const stream = await generateOneOffContentStream(metaPrompt, null, HIKARU_PERSONA, model, config);
      if (stream) {
        for await (const chunk of stream) {
            if (chunk.text) {
                setMessages(prev => prev.map(msg => 
                    msg.id === messageId 
                    ? { ...msg, explanation: (msg.explanation || '') + chunk.text } 
                    : msg
                ));
            }
        }
      }
    } catch (error) {
      console.error("Error fetching explanation:", error);
      setMessages(prev => prev.map(msg => 
        msg.id === messageId 
        ? { ...msg, explanation: "Error: Could not retrieve meta-analysis." } 
        : msg
      ));
    } finally {
        setMessages(prev => prev.map(msg => 
            msg.id === messageId ? { ...msg, isExplanationLoading: false } : msg
        ));
    }
  };

  const requestScenarioSimulation = async (messageId: string) => {
    const messageToSimulate = messages.find(msg => msg.id === messageId);
    if (!messageToSimulate) return;

    setMessages(prev => prev.map(msg => 
        msg.id === messageId ? { ...msg, isSimulating: true } : msg
    ));

    const simulationPrompt = `Based on your previous response: "${messageToSimulate.text}". Generate three distinct scenarios: a best-case outcome, a worst-case outcome, and a most-likely outcome. For each, provide a title, a probability score as a number between 0 and 100, and a concise analysis.`;

    const schema = {
        type: Type.OBJECT,
        properties: {
          scenarios: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                probability: { type: Type.NUMBER },
                analysis: { type: Type.STRING }
              },
              required: ['title', 'probability', 'analysis']
            }
          }
        },
        required: ['scenarios']
    };

    try {
        const { model } = getModelConfig();
        const result = await generateJsonContent(simulationPrompt, schema, model);
        if (result && result.scenarios) {
            setMessages(prev => prev.map(msg => 
                msg.id === messageId ? { ...msg, scenarios: result.scenarios } : msg
            ));
        } else {
            throw new Error("Invalid or empty response from scenario simulation.");
        }
    } catch (error) {
        console.error("Error fetching scenarios:", error);
         setMessages(prev => prev.map(msg => 
            msg.id === messageId 
            ? { ...msg, text: `${msg.text}\n\n[HIKARU - SIMULATION FAILED: Could not generate scenarios.]` } 
            : msg
        ));
    } finally {
        setMessages(prev => prev.map(msg => 
            msg.id === messageId ? { ...msg, isSimulating: false } : msg
        ));
    }
  };


  return (
    <AppContext.Provider value={{ 
        messages, 
        isLoading, 
        sendMessage, 
        isAdvisorMode, 
        setIsAdvisorMode: handleSetIsAdvisorMode, 
        isEfficiencyMode,
        setIsEfficiencyMode: handleSetIsEfficiencyMode,
        isSecurityMode,
        setIsSecurityMode: handleSetIsSecurityMode,
        isThinkingMode,
        setIsThinkingMode: handleSetIsThinkingMode,
        startNewChat,
        isLiveSessionActive,
        toggleLiveSession,
        ethicalStatus,
        interactionCount,
        intentDrift,
        ethicalThreshold,
        isOptimizationModalOpen,
        toggleOptimizationModal,
        handleMessageFeedback,
        requestMessageExplanation,
        satisfactionScore,
        analysisMode,
        setAnalysisMode,
        requestScenarioSimulation
    }}>
      {children}
    </AppContext.Provider>
  );
};

import { GoogleGenAI, LiveServerMessage, Modality, Blob, Chat, Type, Part } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

// FIX: The `LiveSession` type is not exported from "@google/genai".
// It is inferred from the return type of `ai.live.connect` to ensure type safety.
export type LiveSession = Awaited<ReturnType<typeof ai.live.connect>>;

export async function fileToGenerativePart(file: File) {
  const base64EncodedDataPromise = new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: {
      data: await base64EncodedDataPromise,
      mimeType: file.type,
    },
  };
}

export const generateImage = async (prompt: string): Promise<string> => {
    const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: {
          numberOfImages: 1,
          outputMimeType: 'image/png',
          aspectRatio: '1:1',
        },
    });

    if (response.generatedImages && response.generatedImages.length > 0) {
        const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
        return `data:image/png;base64,${base64ImageBytes}`;
    } else {
        throw new Error("No image was generated by the API.");
    }
};

export const startChat = (systemInstruction: string, model: string = 'gemini-3-flash-preview', config: any = {}): Chat => {
  const chat = ai.chats.create({
    model: model,
    config: {
      ...config,
      systemInstruction,
    },
  });
  return chat;
};

export const generateOneOffContentStream = async (
    text: string, 
    attachmentFile: File | null,
    systemInstruction: string,
    model: string = 'gemini-3-flash-preview',
    config: any = {}
) => {
    const parts: any[] = [];
    if (attachmentFile) {
        parts.push(await fileToGenerativePart(attachmentFile));
    }
    if (text.trim()) {
        parts.push({text});
    }

    if (parts.length === 0) return null;

    const result = await ai.models.generateContentStream({
        model: model,
        contents: { parts },
        config: {
          ...config,
          systemInstruction: systemInstruction
        }
    });

    return result;
};

export const generateJsonContent = async (prompt: string, schema: any, model: string = 'gemini-3-flash-preview') => {
    const response = await ai.models.generateContent({
        model: model,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: schema,
        },
    });

    try {
        const jsonText = response.text.trim();
        return JSON.parse(jsonText);
    } catch (e) {
        console.error("Failed to parse JSON response:", response.text);
        throw new Error("Invalid JSON response from model.");
    }
};


